// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;

    // The test contract is c's Owner (msg.sender at deployment) and must be
    // able to RECEIVE the withdrawn ether via transfer(), otherwise the
    // reference itself reverts.
    receive() external payable {}

    function setUp() public { c = new MultiplicatorX3(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1e18);
        vm.deal(address(c), amount);

        bool ok;
        vm.prank(address(this));
        try c.withdraw() { ok = true; } catch { ok = false; }

        assertTrue(ok && address(c).balance == 0);
    }
}
